    // Testbench signals (combinational circuit)
    reg [3:0] binary;
    wire [7:0] twos_complement;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .binary(binary),
        .twos_complement(twos_complement)
    );
    task testcase001;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Input Zero (4'b0000)", test_num);
