Implement the Verilog module based on the following description.
Given the finite state machine circuit described below, assume that the D flip-flops are initially reset to zero before the machine begins.

// Build this circuit in Verilog.

// Input i goes to four different two-input gates: a AND, a OR, a XOR, and a NAND gate. Each of the four gates is connected to the input of a D flip-flop and then the flip-flop outputs all go to a four-input XOR, whose output is X. The second input of the AND is its corresponding flip-flop's output, the second input of the OR is its corresponding flip-flop's complemented output, the second input of the XOR is its corresponding flip-flop's output, and the second input of the NAND is its corresponding flip-flop's complemented output.
module fsm_module10 (
	input clk,
	input i,
	output x);

code:
module fsm_module10 (
	input clk,
	input i,
	output x);reg [3:0] state = 0;

	always @(posedge clk) begin
		state <= { (state[3] & i), (state[2] | i), (state[1] ^ i), ~(state[0] & i) };		
	end

	assign x = state[3] ^ state[2] ^ state[1] ^ state[0];

endmodule

