module shift_register_4bit(
    input clk,          // Clock input
    input load,         // Load signal
    input [3:0] data_in,  // 4-bit parallel input data
    input shift,        // Shift signal

    output [3:0] data_out  // 4-bit output representing the current register contents
);

reg [3:0] register; // Register to hold the data

always @(posedge clk) begin
    if (load)
        register <= data_in; // Load the parallel input data
    else if (shift)
        register <= register << 1; // Shift the register contents to the left
end

assign data_out = register;

endmodule

