    reg [3:0] A;
    reg [3:0] B;
    reg [2:0] op;
    wire [3:0] Z;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .A(A),
        .B(B),
        .op(op),
        .Z(Z)
    );
    task testcase001;

        begin
            test_num = test_num + 1;
            A = 4'd5;
            B = 4'd3;
            op = 3'b000;
            $display("Test %0d: Addition (5 + 3)", test_num);
            #1;

            check_outputs(4'd8);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            A = 4'd12;
            B = 4'd7;
            op = 3'b000;
            $display("Test %0d: Addition with Overflow (12 + 7 = 19 -> 3)", test_num);
            #1;

            check_outputs(4'd3);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            A = 4'd10;
            B = 4'd4;
            op = 3'b001;
            $display("Test %0d: Subtraction (10 - 4)", test_num);
            #1;

            check_outputs(4'd6);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            A = 4'd2;
            B = 4'd5;
            op = 3'b001;
            $display("Test %0d: Subtraction with Underflow (2 - 5 = -3 -> 13)", test_num);
            #1;

            check_outputs(4'd13);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            A = 4'b1100;
            B = 4'b1010;
            op = 3'b010;
            $display("Test %0d: Bitwise AND (1100 & 1010)", test_num);
            #1;

            check_outputs(4'b1000);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            A = 4'b1100;
            B = 4'b1010;
            op = 3'b011;
            $display("Test %0d: Bitwise OR (1100 | 1010)", test_num);
            #1;

            check_outputs(4'b1110);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            A = 4'b1100;
            B = 4'b1010;
            op = 3'b100;
            $display("Test %0d: Bitwise XOR (1100 ^ 1010)", test_num);
            #1;

            check_outputs(4'b0110);
        end
        endtask

    task testcase008;

        begin
            test_num = test_num + 1;
            A = 4'b1010;
            B = 4'b0000;
            op = 3'b101;
            $display("Test %0d: Bitwise NOT (~1010)", test_num);
            #1;

            check_outputs(4'b0101);
        end
        endtask

    task testcase009;

        begin
            test_num = test_num + 1;
            A = 4'b1111;
            B = 4'b1111;
            op = 3'b110;
            $display("Test %0d: Invalid Operation (op=110)", test_num);
            #1;

            check_outputs(4'bxxxx);
        end
        endtask

