description:
Design a traffic light controller that manages a three-color traffic light system using a finite state machine (FSM). The module takes a clock signal as input and outputs a 3-bit wide signal representing the current state of the traffic light: GREEN, YELLOW, or RED. It operates with specific timing parameters where the GREEN light is active for 10 cycles, the YELLOW light for 2 cycles, and the RED light for 10 cycles before cycling back to GREEN. The FSM transitions between these states based on a counters' value, ensuring controlled and periodic changes of the traffic light states.
module top_module(
  input clk,
  output reg [2:0] traffic_light
);

code:
module top_module(
  input clk,
  output reg [2:0] traffic_light
);parameter GREEN = 3'b001;
  parameter YELLOW = 3'b010;
  parameter RED = 3'b100;

  reg [3:0] state;

  always @(posedge clk) begin
    case(state)
      GREEN: begin
        traffic_light <= GREEN;
        if (count == 10) 
          state <= YELLOW;
        else
          count <= count + 1;
      end
      YELLOW: begin
        traffic_light <= YELLOW;
        if (count == 2) 
          state <= RED;
        else
          count <= count + 1;
      end
      RED: begin
        traffic_light <= RED;
        if (count == 10) 
          state <= GREEN;
        else
          count <= count + 1;
      end
      default: state <= GREEN;
    endcase
  end

  reg [3:0] count;

endmodule

