module top_module(SDI, phi1, phi2, read, SDO);input SDI;
  input phi1;
  input phi2;
  input read;
  output reg SDO; // Change SDO to output reg

  reg [7:0] bsr;
  reg shift_enable;
  reg read_enable;
  reg sdi_buffer;

  always @(posedge phi1) begin
    if (read_enable) begin
      SDO <= bsr[0]; // Assign to SDO directly as output reg
      bsr <= {bsr[6:0], sdi_buffer};
    end else if (shift_enable) begin
      bsr <= {bsr[6:0], SDI};
    end
  end

  always @(posedge phi2) begin
    if (shift_enable) begin
      SDO <= bsr[0]; // Same here for SDO
      bsr <= {bsr[6:0], bsr[7]};
    end
  end

  always @(posedge phi1) begin
    if (read) begin
      read_enable <= 1;
      shift_enable <= 0;
    end else begin
      read_enable <= 0;
      shift_enable <= 1;
      sdi_buffer <= SDI;
    end
  end

endmodule

