	input brew,
	output reg brewing);

	parameter IDLE=0, BREWING=1, DONE=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: next_state = brew ? BREWING : IDLE;
			BREWING: next_state = DONE;
			DONE: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	always @(state) begin
		case (state)
			BREWING: brewing = 1;
			default: brewing = 0;
		endcase
	end
endmodule

