	input  iCE_CLK,
	output LED0,
	output LED1,
	output LED2,
	output LED3,
	output LED4,
	output LED5,
	output LED6,
	output LED7
);localparam MAX_VAL = 600000;
	reg [31:0] counter = 0;
	reg [7:0]  shift_reg = 1;

