module top_module(D,
    Q,
    s_aclk,
    AR);output [3:0] Q;
  input [3:0] D;
  input s_aclk;
  input [0:0] AR;

  wire [0:0] AR;
  reg [3:0] Q_reg; // Change to reg to hold the state and ensure synthesis compatibility
  wire s_aclk;

  assign Q = Q_reg;

  always @(posedge s_aclk or posedge AR) begin
    if (AR) 
      Q_reg <= 4'b0; // Reset Q_reg if AR is high
    else 
      Q_reg <= D; // Capture D on the rising edge of s_aclk
  end
endmodule

