module top_module(
    input [18:0] din,
    input rd_clk,
    input rd_en,
    input rst,
    input wr_clk,
    input wr_en,
    output [18:0] dout,
    output empty,
    output full,
    output [4:0] rd_data_count,
    output [4:0] wr_data_count
);reg [18:0] memory [0:15]; // Assuming a depth of 16 for the FIFO
    reg [3:0] wr_pointer = 0;
    reg [3:0] rd_pointer = 0;
    reg [4:0] data_count = 0;

    assign dout = (rd_en && !empty) ? memory[rd_pointer] : 19'b0; // Output data
    assign empty = (data_count == 0);
    assign full = (data_count == 16);
    assign rd_data_count = data_count;
    assign wr_data_count = data_count;

    // Write operation
    always @(posedge wr_clk or posedge rst) begin
        if (rst) begin
            wr_pointer <= 0;
            data_count <= 0;
        end else if (wr_en && !full) begin
            memory[wr_pointer] <= din;
            wr_pointer <= wr_pointer + 1;
            data_count <= data_count + 1;
        end
    end

    // Read operation
    always @(posedge rd_clk or posedge rst) begin
        if (rst) begin
            rd_pointer <= 0;
        end else if (rd_en && !empty) begin
            rd_pointer <= rd_pointer + 1;
            data_count <= data_count - 1;
        end
    end

endmodule

