module top_module(
    input clk,                  // Added clk input
    input [7:0] denom,
    input [63:0] numer,
    output [63:0] quotient,
    output [7:0] remain
);reg [63:0] dividend_reg;
    reg [7:0] divisor_reg;
    reg [7:0] remain_reg;
    reg [63:0] quotient_reg;
    reg [6:0] shift_reg;
    integer i;                  // Declare 'i' as integer

    always @(*) begin
        dividend_reg = numer;
        divisor_reg = denom;
        shift_reg = 0;
        quotient_reg = 0;
        remain_reg = 0;
    end

    always @(posedge clk) begin
        if (dividend_reg[63] == 1) begin
            dividend_reg = dividend_reg - (divisor_reg << 56);
            quotient_reg[63] = 1;
        end

        for (i = 62; i >= 0; i = i - 1) begin
            shift_reg = {shift_reg[5:0], dividend_reg[i]};
            if (shift_reg >= divisor_reg) begin
                quotient_reg[i] = 1;
                shift_reg = shift_reg - divisor_reg;
            end
        end

        remain_reg = shift_reg;
    end

    assign quotient = quotient_reg;
    assign remain = remain_reg;

endmodule

