description:
Design a 4-bit up counter that increments its output on each positive clock edge. The counter resets to zero when the reset input is asserted. The functionality includes internal state tracking using two flip-flop-like registers (j and k), which facilitate the counting mechanism by controlling the conditions under which the count is incremented based on the previous state of the counter.
module top_module(
  input clk,
  input reset,
  output reg [3:0] count_out
);

code:
module top_module(
  input clk,
  input reset,
  output reg [3:0] count_out
);reg j, k;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    count_out <= 4'b0000;
    j <= 1'b0;
    k <= 1'b0;
  end
  else begin
    case ({j,k})
      2'b00: begin // Qn-1 = 0, Qn = 0
        count_out <= count_out + 1;
        j <= 1'b1;
      end
      2'b01: begin // Qn-1 = 0, Qn = 1
        j <= 1'b0;
        k <= 1'b1;
      end
      2'b10: begin // Qn-1 = 1, Qn = 0
        j <= 1'b1;
        k <= 1'b0;
      end
      2'b11: begin // Qn-1 = 1, Qn = 1
        j <= 1'b1;
        k <= 1'b1;
      end
    endcase
  end
end

endmodule

