module top_module(
    input [7:0] anyedge_in, // 8-bit input for the anyedge module
    input [15:0] split_in, // 16-bit input for the split module
    output reg [7:0] sum // 8-bit output for the sum of the two inputs
);// Anyedge module
    reg [7:0] anyedge_out;
    always @(*) begin
        anyedge_out = anyedge_in & (~anyedge_in << 1);
    end

    // Split module
    reg [7:0] split_upper;
    reg [7:0] split_lower;
    always @(*) begin
        split_upper = split_in[15:8];
        split_lower = split_in[7:0];
    end

    // Sum module
    always @(*) begin
        sum = anyedge_out + split_upper + split_lower;
    end

endmodule

