module top_module(
    input  wire [7:0] A,
    input  wire [7:0] B,
    output wire [8:0] S
);wire [8:0] C;

    // First adder
    assign {S[0], C[1]} = A[0] + B[0];

    // Middle adders
    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : adder_loop
            assign {S[i], C[i+1]} = A[i] + B[i] + C[i];
        end
    endgenerate

    // Last adder
    assign {S[8]} = C[8]; // Assign carry out to S[8], no need to add A[8] and B[8]

endmodule

