description:
Design a PWM (Pulse Width Modulation) generator that produces a PWM signal with a variable duty cycle controlled by an 18-bit input switch. The generator uses a 50MHz clock to create a 7-bit counter that iterates from 0 to 99. The least significant 9 bits of the switch input specify the duty cycle, and the PWM output is set high when the counter value is less than the duty cycle value. This implementation allows for flexible control of the signal's power or brightness by adjusting the duty cycle, making it suitable for applications like motor control or LED dimming.
module top_module(
  input         clk, // 50MHz clock
  input  [17:0] sw, // 18-bit input switch
  output        pwm // PWM signal with variable duty cycle
);

code:
module top_module(
  input         clk, // 50MHz clock
  input  [17:0] sw, // 18-bit input switch
  output        pwm // PWM signal with variable duty cycle
);// Convert duty cycle percentage to binary value
  wire [6:0] duty_cycle;
  assign duty_cycle = sw[8:0];

  // Counter that counts from 0 to 99 and resets back to 0
  reg [6:0] count;
  always @(posedge clk) begin
    if (count == 99)
      count <= 0;
    else
      count <= count + 1;
  end

  // Comparator that sets PWM signal high if counter value is less than duty cycle percentage
  reg pwm_out;
  always @(posedge clk) begin
    if (count < duty_cycle)
      pwm_out <= 1'b1;
    else
      pwm_out <= 1'b0;
  end

  // Output PWM signal
  assign pwm = pwm_out;

endmodule

