module top_module(
  input clk,
  input reset,
  input data,
  output reg match
);parameter IDLE = 2'b00, STATE1 = 2'b01, STATE2 = 2'b10;
  reg [1:0] state, next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      IDLE: begin
        if (data == 1) begin
          next_state = STATE1;
        end else begin
          next_state = IDLE;
        end
        match = 0;
      end

      STATE1: begin
        if (data == 0) begin
          next_state = STATE2;
        end else begin
          next_state = STATE1;
        end
        match = 0;
      end

      STATE2: begin
        if (data == 1) begin
          next_state = STATE1;
        end else begin
          next_state = STATE2;
        end
        if (match == 0 && state == STATE2) begin
          match = 1;
        end
      end
    endcase
  end

endmodule

