module top_module(
  input [3:0] in,
  input [1:0] ctrl,
  output reg [3:0] out  // Changed from wire to reg
);reg [1:0] index;
  always @* begin
    index = {ctrl, in[1]};
  end

  // Implement the output using a case statement
  always @* begin
    case (index)
      2'b00: out = 4'b0000; // Updated case conditions
      2'b01: out = 4'b1010;
      2'b10: out = 4'b0101;
      2'b11: out = 4'b1111;
    endcase
  end

endmodule

module counter_4bit (
    input clk,
    input en,
    input rst,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (rst)
            count <= 4'b0;
        else if (en)
            count <= count + 1;
    end
endmodule

